#!/usr/bin/env python3
"""Duty Board v3.262.0 — chat bubbles for the Duty Room and DMs. CSS only.

Applies the change directly to duty_board.js on the server, because the zip
download kept truncating (End-of-central-directory signature not found).

The replacement was derived from a diff of the committed files and verified to
reconstruct the tested version byte for byte — not retyped. One contiguous
block, so nothing can be applied half-way.

Anchored and idempotent: refuses unless the anchor matches exactly once, writes
a .bak first, and reports "already applied" if the CSS is already there.

  python3 patch_3262.py --check     report only, change nothing
  python3 patch_3262.py             apply
"""
import io, os, sys

JS = os.path.expanduser("~/frappe-bench/apps/duty_board/duty_board/duty_board/page/duty_board/duty_board.js")
INIT = os.path.expanduser("~/frappe-bench/apps/duty_board/duty_board/__init__.py")
CHECK = "--check" in sys.argv

